-- PostgreSQL trigger conversion. SQLite FTS5 maintenance triggers are intentionally
-- omitted: search_vector and GIN indexes are native, rebuildable projections.
CREATE OR REPLACE FUNCTION octo_rill_set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS users_set_updated_at ON users;
CREATE TRIGGER users_set_updated_at BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION octo_rill_set_updated_at();
DROP TRIGGER IF EXISTS user_tokens_set_updated_at ON user_tokens;
CREATE TRIGGER user_tokens_set_updated_at BEFORE UPDATE ON user_tokens FOR EACH ROW EXECUTE FUNCTION octo_rill_set_updated_at();
