CREATE OR REPLACE FUNCTION octo_rill_touch_migration_control()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS migration_control_touch_updated_at ON migration_control;
CREATE TRIGGER migration_control_touch_updated_at BEFORE UPDATE ON migration_control
FOR EACH ROW EXECUTE FUNCTION octo_rill_touch_migration_control();
